<script setup lang="ts">import type {Segment} from '../types/domain';import {number} from '../utils/format';import {colors} from '../constants/enums';defineProps<{segment:Segment}>();</script><template><article class="segment-summary" :style="{'--segment':colors[segment.label%colors.length]}"><div class="segment-top"><span>GROUP {{String(segment.label+1).padStart(2,'0')}}</span><strong>{{number(segment.size)}} <small>位</small></strong></div><h3>{{segment.name}}</h3><div class="segment-facts"><span>最近学习 <b>{{number(segment.center.recency,1)}} 天前</b></span><span>累计消费 <b>¥{{number(segment.center.spend)}}</b></span></div><p>{{segment.recommendation}}</p><slot/></article></template>
